const { v4: uuidv4 } = require('uuid')
require('dotenv').config()
const {
  airtable: { apiUrl: AIRTABLE_API, baseMain: AIRTABLE_BASE_MAIN, basePortal: AIRTABLE_BASE_PORTAL, baseWales: AIRTABLE_BASE_WALES },
  firebase: { storageBucket: FIREBASE_STORAGE_BUCKET, functionsApiUrl: PUBLIC_FIREBASE_API },
  openai: { apiUrl: OPENAI_URL, model: OPENAI_MODEL },
  site: { origin: PUBLIC_SITE_URL },
} = require('./config/settings.json')
