// Firebase Admin
const admin = require('firebase-admin')
const storageBucket = FIREBASE_STORAGE_BUCKET
admin.initializeApp({
    storageBucket: storageBucket.startsWith('gs://') ? storageBucket : `gs://${storageBucket}`
})
const db = admin.firestore()
const storage = admin.storage()

// Helper function to get storage bucket name without gs:// prefix
function getStorageBucketName() {
    const bucket = storageBucket.replace(/^gs:\/\//, '')
    return bucket
}

// Helper function to construct Firebase Storage URLs
function getStorageUrl(path) {
    const bucketName = getStorageBucketName()
    const encodedPath = encodeURIComponent(path)
    return `https://firebasestorage.googleapis.com/v0/b/${bucketName}/o/${encodedPath}?alt=media`
}

// PDF Generation
const { generate } = require('@pdfme/generator')
const { text, image } = require('@pdfme/schemas')

