// Add Airtable Files to Firebase Storage

app.post('/files', async (req, res) => {

    const { airtableFilename, airtableFiletype, airtableUrl, firebaseFolder } = req.body
    
    axios({
        method: 'GET',
        url: airtableUrl,
        responseType: 'stream'
    }).then(async response => {
      const file = admin.storage().bucket().file(`${firebaseFolder}/${airtableFilename}`)
      const writeStream = file.createWriteStream({
          contentType: airtableFiletype,
          metadata: {
            metadata :{
              firebaseStorageDownloadTokens: uuidv4()
            }
          },
      })
      await new Promise((resolve, reject) => {
          response.data.pipe(writeStream)
              .on('finish', () => {
                  console.log('Successfully uploaded file')
                  resolve()
              })
              .on('error', (err) => {
                  console.log('Error uploading file')
                  reject(err)
              })
      })
    })
    .then(() => {
        const fileUrl = getStorageUrl(`${firebaseFolder}/${airtableFilename}`)
        console.log("File successfully added with URL:\n" + fileUrl)
        res.status(200).send({firebaseUrl: fileUrl})
    })
    .catch((error) => {
        console.error("Error adding file:", error.message)
        res.status(400).send(JSON.stringify("Error adding file: ", error))
    })
})

