// Generate Postage Label PDF's

app.post('/pdf/postage', async (req, res) => {

  const {
    addresses,
    filename,
    folder,
    xStart,
    yStart,
    xOffset,
    yOffset
  } = req.body

  if (!addresses || !Array.isArray(addresses) || addresses.length === 0) {
      return res.status(400).send({ error: 'Invalid or empty addresses array' })
  }

  if (!xStart || !yStart || !xOffset || !yOffset) {
      return res.status(400).send({ error: 'Missing one or more required position parameters (xStart, yStart, xOffset, yOffset)' })
  }

  // SETTINGS
  const MAX_LABELS_PER_PAGE = 10
  const LABEL_WIDTH = 84.5
  const LABEL_HEIGHT = 45
  const LINE_HEIGHT = 1.2
  const FONT_SIZE = 12

  const schemas = []
  const inputs = []
  let currentPage = {}
  let currentInput = {}

  let currentX = xStart
  let currentY = yStart
  let labelCount = 0

  addresses.forEach((address, index) => {

      const fieldName = `add${(index % MAX_LABELS_PER_PAGE) + 1}`

      // Define Address Schema
      currentPage[fieldName] = {
          type: "text",
          position: {
            x: currentX,
            y: currentY
          },
          width: LABEL_WIDTH,
          height: LABEL_HEIGHT,
          rotate: 0,
          alignment: "left",
          verticalAlignment: "top",
          fontSize: FONT_SIZE,
          lineHeight: LINE_HEIGHT,
          characterSpacing: 0,
          fontColor: "#000000",
          backgroundColor: "",
          opacity: 1,
          fontName: "regular"
      }

      // Add corresponding input value
      currentInput[fieldName] = address

      // Update positions for the next label
      labelCount++;
      if (labelCount % 2 === 0) {
          // Move to the next row after 2 labels
          currentX = xStart;
          currentY += yOffset;
      } else {
          // Move to the second column
          currentX += xOffset;
      }

      // Check if the page is full or we're at the last address
      if (labelCount % MAX_LABELS_PER_PAGE === 0 || index === addresses.length - 1) {
          schemas.push({ ...currentPage })
          inputs.push({ ...currentInput })

          // Reset for the next page
          currentPage = {}
          currentInput = {}
          currentX = xStart
          currentY = yStart
          labelCount = 0
      }
  })

  const plugins = { text, image }
  const font = {
      regular: {
          data: getStorageUrl('fonts/arial.ttf'),
          fallback: true
      }
  }

  const template = {
      schemas,
      basePdf: "data:application/pdf;base64,",
      pdfmeVersion: "4.0.0"
  }

  try {

      const pdf = await generate({ template, plugins, inputs, options: { font } })

      const fileUrl = getStorageUrl(`${folder}/${filename}.pdf`)
      const file = admin.storage().bucket().file(`${folder}/${filename}.pdf`)
      const writeStream = file.createWriteStream({
          contentType: 'application/pdf',
          metadata: {
              metadata: {
                  firebaseStorageDownloadTokens: uuidv4()
              }
          },
      })

      writeStream.write(Buffer.from(pdf.buffer))
      writeStream.end()

      writeStream.on('finish', () => {
          res.status(200).send({ firebaseUrl: fileUrl })
      })

      writeStream.on('error', (err) => {
          res.status(500).send({ error: "Failed to upload file to Firebase Storage" })
      })
  } catch (error) {
      console.error("PDF Generation Error:", error.message)
      console.error("Error Details:", error.stack)
      res.status(500).send({ error: `Failed to generate PDF: ${error.message}` })
  }
})

