// Delete Firebase File

app.post('/files/delete', async (req, res) => {
  const { filePaths, key } = req.body;

  if (key !== process.env.AIRTABLE_PASSWORD) {
      return res.status(401).send({ error: 'Unauthorized Request. Missing or invalid Password.' });
  }

  if (!filePaths || !Array.isArray(filePaths) || !filePaths.every(path => typeof path === 'string')) {
      return res.status(400).send({ error: 'Invalid filePaths. It should be an array of strings.' });
  }

  if (filePaths.length === 0) {
      return res.status(400).send({ error: 'Empty filePaths array. No files to delete.' });
  }

  try {
      const results = await Promise.allSettled(
          filePaths.map(async (filePath) => {
              const file = admin.storage().bucket().file(filePath);
              await file.delete();
              console.log(`File deleted: ${filePath}`);
              return { filePath, success: true };
          })
      );

      // Separate successful and failed results
      const failed = results
          .filter(result => result.status === 'rejected')
          .map(result => ({
              filePath: result.reason?.config?.url || "Unknown", // Fallback if no filePath is present
              error: result.reason?.message || "Unknown error"
          }));

      if (failed.length > 0) {
          return res.status(500).send({
              message: 'Some files could not be deleted.',
              failed
          });
      }

      res.status(200).send({ message: 'All files successfully deleted.' });
  } catch (error) {
      console.error("Unexpected Error:", error.message);
      res.status(500).send({ error: `Unexpected server error: ${error.message}` });
  }
})

