// Process Partner Postage requests

app.post('/submit-postage', async (req, res) => {

  const { people, picklist, title, source, tags } = req.body;

  // Validate request body
  if (!people || !title || !source || !picklist) {
    return res.status(400).send("Missing required fields: 'people', 'title', 'picklist' or 'source'.");
  }

  const existingUsers = []
  const newUsers = []
  let tagIds = []

  // Fetch and resolve Tags
  try {
    // Fetch all tags from the Tags table
    const allTagsResponse = await axios.get(
      `${AIRTABLE_API}/${AIRTABLE_BASE_MAIN}/Tags`,
      {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`,
        },
      }
    );

    const allTags = allTagsResponse.data.records;

    // Map provided tags to their corresponding record IDs
    tagIds = tags.map((tag) => {
      const matchedTag = allTags.find((record) => record.fields.Name === tag);
      if (matchedTag) {
        return matchedTag.id; // Use existing tag ID
      } else {
        console.warn(`Tag '${tag}' not found in the Tags table.`);
        return null; // Handle missing tags gracefully
      }
    }).filter(Boolean); // Remove any null values for unmatched tags

    // Get record ID for parner tag
    // const partnerTag = allTags.find((record) => record.fields.Name === `partner-${source.toLowerCase()}`);
    // tagIds.push(partnerTag.id);

    console.log("Resolved Tag IDs:", tagIds);
  } catch (error) {
    console.error("Error fetching or resolving tags:", error.message);
    return res.status(500).send("Error fetching or resolving tags.");
  }

  // Process People
  try {
    for (const person of people) {
      const email = person.email;

      try {
        // Check if person already exists
        const existingUser = await axios.get(
          `${AIRTABLE_API}/${AIRTABLE_BASE_MAIN}/People?filterByFormula=${encodeURIComponent(`AND({Email}='${email}')`)}`,
          {
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`,
            },
          }
        );

        if (existingUser.data.records.length > 0) {
          if (existingUser.data.records.length > 1) {
            console.warn(`Multiple records found for email: ${email}. Using the first one.`);
          }

          console.log(`Existing User found for ${email}:`, existingUser.data.records[0].id);
          const userId = existingUser.data.records[0].id;
          const currentTags = existingUser.data.records[0].fields["Tags"] || [];
          const updatedTags = [...new Set([...currentTags, ...tagIds])]; // Merge and deduplicate
          console.log("Merged Tags...", updatedTags)

          existingUsers.push(userId)

          // Update person record in Airtable
          const existingPersonPayload = {
            fields: {
              "First Name": person.fname,
              "Last Name": person.lname,
              "Address Line 1": person.add1,
              "Address Line 2": person.add2,
              "City": person.city,
              "Postcode": person.postcode,
              "Country": person.country,
              "Tags": updatedTags,
            },
          }
          console.log("Updating existing Person record...", existingPersonPayload)
          await axios.patch(
            `${AIRTABLE_API}/${AIRTABLE_BASE_MAIN}/People/${existingUser.data.records[0].id}`,
            existingPersonPayload,
            {
              headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`,
              },
            }
          )

        } else {
          
          // Create new person record in Airtable
          const newPersonPayload = {
            fields: {
              "Email": email,
              "First Name": person.fname,
              "Last Name": person.lname,
              "Address Line 1": person.add1,
              "Address Line 2": person.add2,
              "City": person.city,
              "Postcode": person.postcode,
              "Country": person.country,
              "Tags": tagIds,
            },
          }
          console.log("Creating new Person record...", newPersonPayload);
          const newPerson = await axios.post(
            `${AIRTABLE_API}/${AIRTABLE_BASE_MAIN}/People`,
            newPersonPayload,
            {
              headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`,
              },
            }
          );
          newUsers.push(newPerson.data.id)
        }
      } catch (error) {
        console.error(`Error updating or creating person with email: ${email}.`, error.detail)
        return res.status(500).send(`Error updating or creating person with email: ${email}.`)
      }
    }
  } catch (error) {
    console.error("Error checking or creating People records:", error.message)
    return res.status(500).send("Error checking or creating People records.")
  }

  // Add Record to Postage Table in Airtable
  const peopleIds = [...new Set([...existingUsers, ...newUsers])]

  try {
    const postageRecord = await axios.post(
      `${AIRTABLE_API}/${AIRTABLE_BASE_MAIN}/Postage`,
      {
        fields: {
          "People": peopleIds,
          "Source": source,
          "Title": title,
          "Picklist": picklist,
        },
      },
      {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`,
        },
      }
    );

    res.status(200).send({
      msg: `Postage record created successfully!`,
      recordId: postageRecord.data.id,
    })

  } catch (error) {
    if (error.response) {
      console.error("Error creating Postage record:", error.response.data);
    } else {
      console.error("Error creating Postage record:", error.message);
    }
    return res.status(500).send("Error creating Postage record.");
  }
})

