// Search Behaviours with AI

app.post("/search-behaviours", async (req, res) => {
  const { query } = req.body;

  try {
    // Fetch all behaviours from Airtable
    const airtableResponse = await axios.post(
      `${AIRTABLE_API}/${AIRTABLE_BASE_PORTAL}/Behaviours/listRecords`,
      {
        fields: ["Name", "Record ID", "Type"]
      },
      {
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
          Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`
        }
      }
    );

    // Format Behaviours array
    const behaviours = airtableResponse.data.records.map(record => ({
      name: record.fields.Name,
      recordId: record.fields["Record ID"],
      type: record.fields.Type
    }));

    // Prepare the prompt for OpenAI
    const prompt = `
      You are a natural language processing assistant. Match the following user query with related behaviour records from Airtable. 
      Related behaviours are those that conceptually or semantically align with the query, even if the terms do not exactly match.

      For example:
      - Query: "screaming"
        Matches: "shouting out"
      - Query: "running in class"
        Matches: "disruptive movement"

      Query: "${query}"

      Behaviours:
      ${behaviours.map(b => `- Name: ${b.name}, Record ID: ${b.recordId}, Type: ${b.type}`).join('\n')}
    `;

    // Define the OpenAI function schema
    const functionDefinition = {
      name: "match_behaviours",
      description: "Match the query to related behaviours from Airtable.",
      parameters: {
        type: "object",
        properties: {
          matches: {
            type: "array",
            description: "List of matched behaviours",
            items: {
              type: "object",
              properties: {
                "Record ID": { type: "string", description: "The Airtable record ID" },
                "Name": { type: "string", description: "The name of the behaviour" },
                "Type": { type: "string", description: "The type of the behaviour" }
              },
              required: ["Record ID", "Name", "Type"]
            }
          }
        },
        required: ["matches"]
      }
    };

    // Make a request to OpenAI API with the function
    const openAiResponse = await axios.post(
      OPENAI_URL,
      {
        model: OPENAI_MODEL,
        messages: [{ role: "user", content: prompt }],
        functions: [functionDefinition],
        function_call: { name: "match_behaviours" }
      },
      {
        headers: {
          Authorization: `Bearer ${process.env.OPENAI_API_KEY}`,
          "Content-Type": "application/json"
        }
      }
    );

    // Extract the structured response
    const matchingRecords = openAiResponse.data.choices[0]?.message?.function_call?.arguments;
    const parsedRecords = JSON.parse(matchingRecords);

    // Respond with the matching records
    console.log("Matching records:", parsedRecords.matches);
    res.status(200).json({ matches: parsedRecords.matches });

  } catch (error) {
    console.error("Error:", error.message);
    res.status(400).send("Error getting behaviour search results.");
  }
});

