app.post('/email-queue', async (req, res) => {

  const { recipients, zapUrl, delay } = req.body;

  try {
      if (req.method !== "POST") {
          return res.status(405).send("Method Not Allowed");
      }

      if (!Array.isArray(recipients) || recipients.length === 0) {
          return res.status(400).send("Invalid or empty recipients array.");
      }

      if (!zapUrl) {
          return res.status(400).send("Missing Zapier webhook URL.");
      }

      if (!delay || isNaN(delay) || delay < 0) {
          return res.status(400).send("Invalid delay value.");
      }

      console.log(`Received ${recipients.length} email requests.`);

      // Process emails sequentially with a delay
      for (const recipient of recipients) {
          await new Promise(resolve => setTimeout(resolve, delay)); // Delay before sending

          try {
              console.log(`Sending email to ${recipient.email}...`);
              await axios.post(zapUrl, recipient);
              console.log(`Email sent successfully to ${recipient.email}`);
          } catch (error) {
              console.error(`Error sending email to ${recipient.email}:`, error.message);
          }
      }

      res.status(200).send(`Queued ${recipients.length} emails for processing.`);

  } catch (error) {
      console.error("Error processing email queue:", error.message);
      res.status(500).send("Internal Server Error");
  }
});

