/**
 * Get schema mapping for a partner
 * Returns the partner's table/field names, or defaults to TISUK names if no mapping exists
 */
const getPartnerSchema = (partnerCode) => {
  const mapping = partnerSchemaMappings[partnerCode] || {};
  
  return {
    // Get partner table name for a TISUK table name
    getTableName: (tisukTableName) => {
      return mapping.tables?.[tisukTableName] || tisukTableName;
    },
    // Get partner field name for a partner table and TISUK field name
    // Note: field mappings are keyed by partner table name
    getFieldName: (partnerTableName, tisukFieldName) => {
      return mapping.fields?.[partnerTableName]?.[tisukFieldName] || tisukFieldName;
    }
  };
};

app.post('/partner-sync/courses', async (req, res) => {

  try {

    const {
      partnerCode,
      partnersRecordId,
      partnerAppId: partnerAppIdFromBody,
      scheduledCourseId
    } = req.body || {};

    const partnerAppId =
      partnerAppIdFromBody || partnerSchemaMappings[partnerCode]?.airtableBaseId;

    if (!partnerCode || !partnersRecordId || !partnerAppId || !scheduledCourseId) {
      return res.status(400).send({
        error: "Missing required fields. Expecting partnerCode, partnersRecordId, scheduledCourseId, and partnerAppId (or a known partnerCode with a base ID in settings)."
      });
    }

    // Get schema mapping for this partner
    const schema = getPartnerSchema(partnerCode);

    // Basic summary object to report what happened in this sync
    const syncSummary = {
      scheduledCourse: {
        action: null,
        id: null,
        name: null
      },
      scheduledDays: {
        source: 0,
        created: 0,
        updated: 0
      },
      applications: {
        // total enrolment records referenced on the Scheduled Course in the partner base
        source: 0,
        created: 0,
        updated: 0,
        deleted: 0
      },
      people: {
        // number of active enrolments from partner (one per enrolment before de-duplication)
        source: 0,
        created: 0,
        updated: 0
      },
      organisations: {
        // number of distinct partner organisations referenced by active enrolments
        source: 0,
        created: 0,
        updated: 0
      },
      trainers: {
        created: 0,
        updated: 0
      },
      trainerBookings: {
        created: 0,
        updated: 0,
        deleted: 0
      }
    };

    const syncedAt = new Date().toISOString();

    // Get partner table/field names
    const partnerScheduledCoursesTable = schema.getTableName("Scheduled Courses");
    const partnerScheduledDaysTable = schema.getTableName("Scheduled Days");
    const partnerEnrolmentsTable = schema.getTableName("Applications");
    const partnerOrganisationsTable = schema.getTableName("Organisations");

    const airtableUrl = `${AIRTABLE_API}/${partnerAppId}/${encodeURIComponent(partnerScheduledCoursesTable)}/${scheduledCourseId}`;

    const airtableResponse = await axios.get(airtableUrl, {
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`
      }
    });

    const tisukTypeField = schema.getFieldName(partnerScheduledCoursesTable, "Type");
    const tisukType = airtableResponse.data?.fields?.[tisukTypeField]?.[0] ?? null;

    const scheduledDaysField = schema.getFieldName(partnerScheduledCoursesTable, "Scheduled Days");
    const scheduledDayIds = airtableResponse.data?.fields?.[scheduledDaysField] || [];

    const courseIdField = schema.getFieldName(partnerScheduledCoursesTable, "Course ID");
    const partnerCourseTitle = airtableResponse.data?.fields?.[courseIdField] ?? null;
    let scheduledDays = [];

    if (scheduledDayIds.length) {
      const scheduledDayRequests = scheduledDayIds.map((scheduledDayId) =>
        axios.get(
          `${AIRTABLE_API}/${partnerAppId}/${encodeURIComponent(partnerScheduledDaysTable)}/${scheduledDayId}`,
          {
            headers: {
              Accept: "application/json",
              Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`
            }
          }
        )
      );

      const scheduledDayResponses = await Promise.allSettled(scheduledDayRequests);

      scheduledDays = scheduledDayResponses
        .filter((result) => result.status === "fulfilled")
        .map((result) => {
          const record = result.value.data;
          const fields = record?.fields || {};

          // Get field names using partner table name (since mapping is keyed by partner table)
          const dayNumberField = schema.getFieldName(partnerScheduledDaysTable, "Course Day No.");
          const dateField = schema.getFieldName(partnerScheduledDaysTable, "Date");
          const startTimeField = schema.getFieldName(partnerScheduledDaysTable, "Start Time");
          const endTimeField = schema.getFieldName(partnerScheduledDaysTable, "End Time");
          const onlineField = schema.getFieldName(partnerScheduledDaysTable, "Online");
          const venueField = schema.getFieldName(partnerScheduledDaysTable, "Venue");
          const trainersField = schema.getFieldName(partnerScheduledDaysTable, "Trainers");
          const trainerEmailsField = schema.getFieldName(partnerScheduledDaysTable, "Trainer Emails");
          const trainerBookingIdsField = schema.getFieldName(partnerScheduledDaysTable, "Trainer Booking ID's");
          const trainerIdsField = schema.getFieldName(partnerScheduledDaysTable, "Trainer IDs");

          const trainerNames = Array.isArray(fields[trainersField]) ? fields[trainersField] : [];
          const trainerEmails = Array.isArray(fields[trainerEmailsField]) ? fields[trainerEmailsField] : [];
          const trainerBookingIds = Array.isArray(fields[trainerBookingIdsField]) ? fields[trainerBookingIdsField] : [];
          const trainerIds = Array.isArray(fields[trainerIdsField]) ? fields[trainerIdsField] : [];

          const trainers = trainerNames.map((name, index) => ({
            name,
            email: trainerEmails[index] ?? null,
            partnerTrainerId: trainerIds[index] ?? null,
            partnerTrainerBookingId: trainerBookingIds[index] ?? null
          }));

          return {
            id: record?.id,
            dayNumber: fields[dayNumberField] ?? null,
            date: fields[dateField] ?? null,
            startTime: fields[startTimeField] ?? null,
            endTime: fields[endTimeField] ?? null,
            online: fields[onlineField] ?? null,
            venue: fields[venueField] ?? null,
            trainers
          };
        });

      const rejectedScheduledDays = scheduledDayResponses.filter((result) => result.status === "rejected");

      if (rejectedScheduledDays.length) {
        console.warn(`Failed to fetch ${rejectedScheduledDays.length} scheduled day records.`);
      }
    }

    const enrolmentIdsField = schema.getFieldName(partnerScheduledCoursesTable, "Enrolment IDs");
    const enrolmentIds = airtableResponse.data?.fields?.[enrolmentIdsField] || [];
    let enrolments = [];
    let cancelledApplicationPartnerIds = [];

    if (enrolmentIds.length) {
      const enrolmentRequests = enrolmentIds.map((enrolmentId) =>
        axios.get(
          `${AIRTABLE_API}/${partnerAppId}/${encodeURIComponent(partnerEnrolmentsTable)}/${enrolmentId}`,
          {
            headers: {
              Accept: "application/json",
              Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`
            }
          }
        )
      );

      const enrolmentResponses = await Promise.allSettled(enrolmentRequests);

      // Get enrolment field names
      const processedField = schema.getFieldName(partnerEnrolmentsTable, "Processed");
      const cancelledField = schema.getFieldName(partnerEnrolmentsTable, "Cancelled");
      const organisationField = schema.getFieldName(partnerEnrolmentsTable, "Organisation");

      const enrichedEnrolments = enrolmentResponses
        .filter((result) => result.status === "fulfilled")
        .map((result) => {
          const record = result.value.data;
          const fields = record?.fields || {};

          const processed = !!fields[processedField];
          const cancelled = !!fields[cancelledField];

          return {
            record,
            fields,
            processed,
            cancelled
          };
        });

      const activeEnrolments = enrichedEnrolments.filter(
        (item) => item.processed && !item.cancelled
      );

      cancelledApplicationPartnerIds = enrichedEnrolments
        .filter((item) => item.cancelled)
        .map((item) => item.record?.id)
        .filter((id) => !!id);

      // Collect unique organisation IDs from the active enrolments
      const organisationIdSet = new Set(
        activeEnrolments
          .map((item) => {
            const fields = item.fields || {};
            return Array.isArray(fields[organisationField]) ? fields[organisationField][0] : null;
          })
          .filter((id) => !!id)
      );

      // Update summary source counts now that we know the active enrolments and distinct organisations
      syncSummary.people.source = activeEnrolments.length;
      syncSummary.organisations.source = organisationIdSet.size;

      let organisationsById = {};

      if (organisationIdSet.size > 0) {
        const organisationIds = Array.from(organisationIdSet);

        const organisationRequests = organisationIds.map((organisationId) =>
          axios.get(
            `${AIRTABLE_API}/${partnerAppId}/${encodeURIComponent(partnerOrganisationsTable)}/${organisationId}`,
            {
              headers: {
                Accept: "application/json",
                Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`
              }
            }
          )
        );

        const organisationResponses = await Promise.allSettled(organisationRequests);

        // Get organisation field names
        const orgNameField = schema.getFieldName(partnerOrganisationsTable, "Name");
        const orgAddressLine1Field = schema.getFieldName(partnerOrganisationsTable, "Address Line 1");
        const orgAddressLine2Field = schema.getFieldName(partnerOrganisationsTable, "Address Line 2");
        const orgCityField = schema.getFieldName(partnerOrganisationsTable, "City");
        const orgPostcodeField = schema.getFieldName(partnerOrganisationsTable, "Postcode");
        const orgCountyField = schema.getFieldName(partnerOrganisationsTable, "County");

        organisationResponses.forEach((result, index) => {
          if (result.status === "fulfilled") {
            const record = result.value.data;
            const fields = record?.fields || {};
            const id = record?.id || organisationIds[index];

            organisationsById[id] = {
              partnerRecordId: id,
              name: fields[orgNameField] ?? null,
              addressLine1: fields[orgAddressLine1Field] ?? null,
              addressLine2: fields[orgAddressLine2Field] ?? null,
              city: fields[orgCityField] ?? null,
              postcode: fields[orgPostcodeField] ?? null,
              county: fields[orgCountyField] ?? null
            };
          }
        });
      }

      const getStringField = (value) => {
        if (Array.isArray(value)) {
          return value[0] ?? null;
        }
        return value ?? null;
      };

      // Get enrolment field names
      const peopleField = schema.getFieldName(partnerEnrolmentsTable, "People");
      const packCardsField = schema.getFieldName(partnerEnrolmentsTable, "Pack - Cards");
      const packLanguageField = schema.getFieldName(partnerEnrolmentsTable, "Pack - Language");
      const packAppendixField = schema.getFieldName(partnerEnrolmentsTable, "Pack - Appendix");
      const displayNameField = schema.getFieldName(partnerEnrolmentsTable, "Display Name");
      const emailField = schema.getFieldName(partnerEnrolmentsTable, "Email");
      const roleField = schema.getFieldName(partnerEnrolmentsTable, "Role");
      const phoneField = schema.getFieldName(partnerEnrolmentsTable, "Phone");
      const addressLine1Field = schema.getFieldName(partnerEnrolmentsTable, "Address Line 1");
      const addressLine2Field = schema.getFieldName(partnerEnrolmentsTable, "Address Line 2");
      const cityField = schema.getFieldName(partnerEnrolmentsTable, "City");
      const countyCouncilField = schema.getFieldName(partnerEnrolmentsTable, "County Council");
      const postcodeField = schema.getFieldName(partnerEnrolmentsTable, "Postcode");

      enrolments = activeEnrolments.map((item) => {
        const { record, fields } = item;

        const partnerPersonId = Array.isArray(fields[peopleField]) ? fields[peopleField][0] : null;
        const partnerOrganisationId = Array.isArray(fields[organisationField]) ? fields[organisationField][0] : null;

        return {
          id: record?.id,
          partnerPersonId,
          partnerOrganisationId,
          processed: item.processed,
          cancelled: item.cancelled,
          packCards: fields[packCardsField] ?? null,
          packLanguage: fields[packLanguageField] ?? null,
          packAppendix: fields[packAppendixField] ?? null,
          people: {
            partnerRecordId: partnerPersonId,
            displayName: getStringField(fields[displayNameField]),
            email: getStringField(fields[emailField]),
            role: getStringField(fields[roleField]),
            phone: getStringField(fields[phoneField]),
            addressLine1: getStringField(fields[addressLine1Field]),
            addressLine2: getStringField(fields[addressLine2Field]),
            city: getStringField(fields[cityField]),
            county: getStringField(fields[countyCouncilField]),
            postcode: getStringField(fields[postcodeField])
          },
          organisation: partnerOrganisationId
            ? {
                ...organisationsById[partnerOrganisationId],
                partnerRecordId: partnerOrganisationId
              }
            : null
        };
      });

      const rejectedEnrolments = enrolmentResponses.filter((result) => result.status === "rejected");

      if (rejectedEnrolments.length) {
        console.warn(`Failed to fetch ${rejectedEnrolments.length} enrolment records.`);
      }
    }

    // --------------------------- SYNC TO TISUK AIRTABLE (Scheduled Course + Scheduled Days)

    const tisukBaseId = AIRTABLE_BASE_MAIN;

    if (!tisukBaseId) {
      throw new Error("AIRTABLE_BASE_MAIN is not configured");
    }

    const airtableHeadersWithJson = {
      Accept: "application/json",
      "Content-Type": "application/json",
      Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`
    };

    // Populate source counts now that we have scheduledDays and enrolmentIds
    syncSummary.scheduledDays.source = scheduledDays.length;
    syncSummary.applications.source = enrolmentIds.length;

    // 1. Resolve Course Type in TISUK Course Types table, based on tisukType
    let courseTypeRecordId = null;

    if (tisukType) {
      try {
        const courseTypeResponse = await axios.post(
          `${AIRTABLE_API}/${tisukBaseId}/Course%20Types/listRecords`,
          {
            fields: ["Type"],
            filterByFormula: `{Type} = "${tisukType}"`
          },
          {
            headers: airtableHeadersWithJson
          }
        );

        const courseTypeRecord = courseTypeResponse.data?.records?.[0];
        if (courseTypeRecord) {
          courseTypeRecordId = courseTypeRecord.id;
        }
      } catch (error) {
        console.warn("Failed to resolve Course Type in TISUK base.", error.message);
      }
    }

    // 2. Upsert Scheduled Course in TISUK

    let tisukScheduledCourseId = null;

    try {
      const existingScheduledCourseResponse = await axios.post(
        `${AIRTABLE_API}/${tisukBaseId}/Scheduled%20Courses/listRecords`,
        {
          maxRecords: 1,
          filterByFormula: `{Partner Record ID} = "${scheduledCourseId}"`
        },
        {
          headers: airtableHeadersWithJson
        }
      );

      const existingScheduledCourse = existingScheduledCourseResponse.data?.records?.[0] || null;

      const scheduledCourseFields = {
        Partner: partnersRecordId ? [partnersRecordId] : [],
        "Partner Record ID": scheduledCourseId,
        "Partner Synced At": syncedAt,
        // In TISUK, Course Title is computed; we write the incoming Course Title into Course ID instead.
        "Course ID": partnerCourseTitle
      };

      if (courseTypeRecordId) {
        scheduledCourseFields["Type"] = [courseTypeRecordId];
      }

      if (existingScheduledCourse) {
        tisukScheduledCourseId = existingScheduledCourse.id;

        await axios.patch(
          `${AIRTABLE_API}/${tisukBaseId}/Scheduled%20Courses/${tisukScheduledCourseId}`,
          {
            fields: scheduledCourseFields
          },
          {
            headers: airtableHeadersWithJson
          }
        );

        syncSummary.scheduledCourse.action = "updated";
        syncSummary.scheduledCourse.id = tisukScheduledCourseId;
      } else {
        const createdScheduledCourseResponse = await axios.post(
          `${AIRTABLE_API}/${tisukBaseId}/Scheduled%20Courses`,
          {
            fields: scheduledCourseFields
          },
          {
            headers: airtableHeadersWithJson
          }
        );

        tisukScheduledCourseId = createdScheduledCourseResponse.data?.id || null;

        syncSummary.scheduledCourse.action = "created";
        syncSummary.scheduledCourse.id = tisukScheduledCourseId;
      }

      syncSummary.scheduledCourse.name = partnerCourseTitle;
    } catch (error) {
      console.error("Error upserting Scheduled Course in TISUK base.", error.message);
      if (error.response) {
        console.error("Airtable error status:", error.response.status);
        console.error("Airtable error data:", JSON.stringify(error.response.data, null, 2));
      }
      throw error;
    }

    // 3. Sync Scheduled Days in TISUK for this Scheduled Course (upsert by Partner Record ID, no mass delete)

    if (tisukScheduledCourseId) {
      try {
        // Upsert incoming days one by one by Partner Record ID
        for (const day of scheduledDays) {
          const dayFields = {
            "Partner Record ID": day.id,
            "Partner Synced At": syncedAt,
            "Course ID": [tisukScheduledCourseId],
            "Day No.": day.dayNumber != null ? String(day.dayNumber) : null,
            "Date": day.date ?? null,
            "Start Time": Array.isArray(day.startTime) ? day.startTime[0] : day.startTime ?? null,
            "End Time": Array.isArray(day.endTime) ? day.endTime[0] : day.endTime ?? null,
            Online: !!day.online,
            Venue: day.venue ?? null
          };

          // Look for an existing Scheduled Day in TISUK with this Partner Record ID
          const existingDayResponse = await axios.post(
            `${AIRTABLE_API}/${tisukBaseId}/Scheduled%20Days/listRecords`,
            {
              maxRecords: 1,
              filterByFormula: `{Partner Record ID} = "${day.id}"`
            },
            {
              headers: airtableHeadersWithJson
            }
          );

          const existingDayRecord = existingDayResponse.data?.records?.[0] || null;

          if (existingDayRecord) {
            await axios.patch(
              `${AIRTABLE_API}/${tisukBaseId}/Scheduled%20Days/${existingDayRecord.id}`,
              {
                fields: dayFields
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            syncSummary.scheduledDays.updated += 1;
          } else {
            await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/Scheduled%20Days`,
              {
                fields: dayFields
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            syncSummary.scheduledDays.created += 1;
          }
        }
      } catch (error) {
        console.error("Error syncing Scheduled Days in TISUK base.", error.message);
        if (error.response) {
          console.error("Airtable Scheduled Days error status:", error.response.status);
          console.error("Airtable Scheduled Days error data:", JSON.stringify(error.response.data, null, 2));
        }
        throw error;
      }
    }

    // 4. Sync Trainers and Trainer Bookings in TISUK

    if (tisukScheduledCourseId && scheduledDays.length) {
      const trainerCache = {};
      const trainerBookingCache = {};

      // Helper to upsert a trainer in TISUK Trainers table
      const upsertTrainer = async (trainer) => {
        if (!trainer || (!trainer.email && !trainer.name)) {
          return null;
        }

        const email = (trainer.email || "").trim();
        const normalisedEmail = email.toLowerCase();
        const displayName = (trainer.name || "").trim();
        const normalisedName = displayName.toLowerCase();
        const partnerTrainerId = trainer.partnerTrainerId || null;
        const trainerKey = partnerTrainerId || normalisedEmail || `name:${normalisedName}`;

        if (trainerCache[trainerKey]) {
          return trainerCache[trainerKey];
        }

        let trainerId = null;

        try {
          // First, find or create the Person
          let personId = null;
          let existingPerson = null;

          if (email) {
            const existingByEmailResponse = await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/People/listRecords`,
              {
                maxRecords: 1,
                filterByFormula: `LOWER(TRIM({Email})) = "${normalisedEmail}"`
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            existingPerson = existingByEmailResponse.data?.records?.[0] || null;
          }

          if (!existingPerson && displayName) {
            const existingByNameResponse = await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/People/listRecords`,
              {
                maxRecords: 1,
                filterByFormula: `LOWER(TRIM({Full Name})) = "${normalisedName}"`
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            existingPerson = existingByNameResponse.data?.records?.[0] || null;
          }

          if (existingPerson) {
            personId = existingPerson.id;
          } else {
            // Create person if they don't exist
            const personFields = {
              Email: email || null,
              "Full Name": displayName || null
            };

            const createdPersonResponse = await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/People`,
              {
                fields: personFields
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            personId = createdPersonResponse.data?.id || null;
          }

          if (!personId) {
            return null;
          }

          // Check if Person already has a Trainer link
          const personResponse = await axios.get(
            `${AIRTABLE_API}/${tisukBaseId}/People/${personId}`,
            {
              headers: {
                Accept: "application/json",
                Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`
              }
            }
          );

          const personFields = personResponse.data?.fields || {};
          const existingTrainerLink = Array.isArray(personFields["Trainer"]) ? personFields["Trainer"][0] : null;

          if (existingTrainerLink) {
            // Person already has a Trainer record, use it
            trainerId = existingTrainerLink;

            // Update the Trainer with partner metadata if we have it
            if (partnerTrainerId) {
              const trainerFields = {
                "Partner Record ID": partnerTrainerId,
                "Partner Synced At": syncedAt
              };

              await axios.patch(
                `${AIRTABLE_API}/${tisukBaseId}/Trainers/${trainerId}`,
                {
                  fields: trainerFields
                },
                {
                  headers: airtableHeadersWithJson
                }
              );

              syncSummary.trainers.updated += 1;
            }
          } else {
            // Create a new Trainer record linked to the Person
            const trainerFields = {
              "People": [personId],
              "Partner Synced At": syncedAt
            };

            if (partnerTrainerId) {
              trainerFields["Partner Record ID"] = partnerTrainerId;
            }

            const createdTrainerResponse = await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/Trainers`,
              {
                fields: trainerFields
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            trainerId = createdTrainerResponse.data?.id || null;

            // Update the Person to link to the Trainer
            if (trainerId) {
              await axios.patch(
                `${AIRTABLE_API}/${tisukBaseId}/People/${personId}`,
                {
                  fields: {
                    "Trainer": [trainerId]
                  }
                },
                {
                  headers: airtableHeadersWithJson
                }
              );

              syncSummary.trainers.created += 1;
            }
          }
        } catch (error) {
          console.error("Error upserting Trainer in TISUK base.", error.message);
          if (error.response) {
            console.error("Airtable Trainer error status:", error.response.status);
            console.error("Airtable Trainer error data:", JSON.stringify(error.response.data, null, 2));
          }
          throw error;
        }

        trainerCache[trainerKey] = trainerId;
        return trainerId;
      };

      // Step 1: Collect all TISUK Scheduled Day IDs and build trainer booking map
      const tisukScheduledDayMap = new Map(); // partner day ID -> TISUK day ID
      const bookingDataMap = new Map(); // partner booking ID -> { trainerId, scheduledDayIds: Set }

      for (const day of scheduledDays) {
        try {
          // Get the TISUK Scheduled Day record ID
          const existingDayResponse = await axios.post(
            `${AIRTABLE_API}/${tisukBaseId}/Scheduled%20Days/listRecords`,
            {
              maxRecords: 1,
              filterByFormula: `{Partner Record ID} = "${day.id}"`
            },
            {
              headers: airtableHeadersWithJson
            }
          );

          const tisukScheduledDay = existingDayResponse.data?.records?.[0];
          if (!tisukScheduledDay) {
            continue; // Skip if day wasn't found/created
          }

          const tisukScheduledDayId = tisukScheduledDay.id;
          tisukScheduledDayMap.set(day.id, tisukScheduledDayId);

          // Collect trainer booking data for this day
          for (const trainer of day.trainers) {
            if (!trainer.partnerTrainerBookingId) {
              continue; // Skip if no booking ID
            }

            // Upsert trainer first to get TISUK trainer ID
            const trainerId = await upsertTrainer(trainer);
            if (!trainerId) {
              continue;
            }

            // Add this scheduled day to the booking's set
            if (!bookingDataMap.has(trainer.partnerTrainerBookingId)) {
              bookingDataMap.set(trainer.partnerTrainerBookingId, {
                trainerId,
                scheduledDayIds: new Set()
              });
            }
            bookingDataMap.get(trainer.partnerTrainerBookingId).scheduledDayIds.add(tisukScheduledDayId);
          }
        } catch (error) {
          console.error("Error collecting trainer booking data.", error.message);
          if (error.response) {
            console.error("Airtable error status:", error.response.status);
            console.error("Airtable error data:", JSON.stringify(error.response.data, null, 2));
          }
          throw error;
        }
      }

      // Step 2: Check which bookings already exist
      const existingBookingsMap = new Map(); // partner booking ID -> TISUK booking record
      const incomingBookingPartnerIds = new Set(bookingDataMap.keys());

      if (incomingBookingPartnerIds.size > 0) {
        try {
          // Fetch all existing bookings for these partner booking IDs
          const partnerBookingIdsArray = Array.from(incomingBookingPartnerIds);
          const filterFormula = `OR(${partnerBookingIdsArray.map(id => `{Partner Record ID} = "${id}"`).join(', ')})`;

          const existingBookingsResponse = await axios.post(
            `${AIRTABLE_API}/${tisukBaseId}/Trainer%20Bookings/listRecords`,
            {
              fields: ["Partner Record ID", "Scheduled Days"],
              filterByFormula: filterFormula
            },
            {
              headers: airtableHeadersWithJson
            }
          );

          const existingBookings = existingBookingsResponse.data?.records || [];
          for (const booking of existingBookings) {
            const partnerBookingId = booking.fields?.["Partner Record ID"];
            if (partnerBookingId) {
              existingBookingsMap.set(partnerBookingId, booking);
            }
          }
        } catch (error) {
          console.error("Error fetching existing trainer bookings.", error.message);
          if (error.response) {
            console.error("Airtable error status:", error.response.status);
            console.error("Airtable error data:", JSON.stringify(error.response.data, null, 2));
          }
          throw error;
        }
      }

      // Step 3: Create all new bookings
      for (const [partnerBookingId, bookingData] of bookingDataMap.entries()) {
        if (!existingBookingsMap.has(partnerBookingId)) {
          try {
            const bookingFields = {
              "Partner Record ID": partnerBookingId,
              "Partner Synced At": syncedAt,
              "Scheduled Days": Array.from(bookingData.scheduledDayIds),
              "Trainer": [bookingData.trainerId]
            };

            await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/Trainer%20Bookings`,
              {
                fields: bookingFields
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            syncSummary.trainerBookings.created += 1;
          } catch (error) {
            console.error("Error creating trainer booking.", error.message);
            if (error.response) {
              console.error("Airtable error status:", error.response.status);
              console.error("Airtable error data:", JSON.stringify(error.response.data, null, 2));
            }
            throw error;
          }
        }
      }

      // Step 4: Update all existing bookings with complete scheduled days arrays
      for (const [partnerBookingId, bookingData] of bookingDataMap.entries()) {
        const existingBooking = existingBookingsMap.get(partnerBookingId);
        if (existingBooking) {
          try {
            const bookingFields = {
              "Partner Record ID": partnerBookingId,
              "Partner Synced At": syncedAt,
              "Scheduled Days": Array.from(bookingData.scheduledDayIds),
              "Trainer": [bookingData.trainerId]
            };

            await axios.patch(
              `${AIRTABLE_API}/${tisukBaseId}/Trainer%20Bookings/${existingBooking.id}`,
              {
                fields: bookingFields
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            syncSummary.trainerBookings.updated += 1;
          } catch (error) {
            console.error("Error updating trainer booking.", error.message);
            if (error.response) {
              console.error("Airtable error status:", error.response.status);
              console.error("Airtable error data:", JSON.stringify(error.response.data, null, 2));
            }
            throw error;
          }
        }
      }

      // Step 5: Cleanup - remove days from bookings that are no longer in partner data
      // Get all existing bookings linked to any of our scheduled days
      if (tisukScheduledDayMap.size > 0) {
        try {
          const tisukDayIdsArray = Array.from(tisukScheduledDayMap.values());
          // Use exact matching instead of substring matching to avoid false positives
          // e.g., "rec12" should not match "rec123"
          const filterFormula = `OR(${tisukDayIdsArray.map(id => `FIND(",${id},", "," & ARRAYJOIN({Scheduled Days}, ",") & ",")`).join(', ')})`;

          const allLinkedBookingsResponse = await axios.post(
            `${AIRTABLE_API}/${tisukBaseId}/Trainer%20Bookings/listRecords`,
            {
              fields: ["Partner Record ID", "Scheduled Days"],
              filterByFormula: filterFormula
            },
            {
              headers: airtableHeadersWithJson
            }
          );

          const allLinkedBookings = allLinkedBookingsResponse.data?.records || [];
          const validDayIds = new Set(tisukScheduledDayMap.values());

          for (const booking of allLinkedBookings) {
            const partnerBookingId = booking.fields?.["Partner Record ID"];
            
            // Skip if this booking is in our incoming data (already handled above)
            if (incomingBookingPartnerIds.has(partnerBookingId)) {
              continue;
            }

            // Remove our scheduled days from this booking
            const existingScheduledDays = Array.isArray(booking.fields?.["Scheduled Days"]) 
              ? booking.fields["Scheduled Days"] 
              : [];
            
            const updatedScheduledDays = existingScheduledDays.filter(id => !validDayIds.has(id));

            if (updatedScheduledDays.length === 0) {
              // No more days, delete the booking
              await axios.delete(
                `${AIRTABLE_API}/${tisukBaseId}/Trainer%20Bookings/${booking.id}`,
                {
                  headers: {
                    Accept: "application/json",
                    Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`
                  }
                }
              );

              syncSummary.trainerBookings.deleted += 1;
            } else if (updatedScheduledDays.length !== existingScheduledDays.length) {
              // Update booking to remove our days
              await axios.patch(
                `${AIRTABLE_API}/${tisukBaseId}/Trainer%20Bookings/${booking.id}`,
                {
                  fields: {
                    "Scheduled Days": updatedScheduledDays
                  }
                },
                {
                  headers: airtableHeadersWithJson
                }
              );

              syncSummary.trainerBookings.updated += 1;
            }
          }
        } catch (error) {
          console.error("Error cleaning up trainer bookings.", error.message);
          if (error.response) {
            console.error("Airtable error status:", error.response.status);
            console.error("Airtable error data:", JSON.stringify(error.response.data, null, 2));
          }
          throw error;
        }
      }
    }

    // 5. Sync Applications (and upsert People/Organisations) in TISUK

    if (tisukScheduledCourseId && enrolments.length) {
      const peopleCache = {};
      const organisationCache = {};

      // Helper to upsert an organisation in TISUK Organisations table
      const upsertOrganisation = async (organisation) => {
        if (!organisation || !organisation.name) {
          return null;
        }

        const partnerOrganisationRecordId = organisation.partnerRecordId || null;
        const normalisedName = (organisation.name || "").trim().toLowerCase();
        const normalisedPostcode = (organisation.postcode || "").trim().toLowerCase();
        const cacheKey = partnerOrganisationRecordId || `${normalisedName}||${normalisedPostcode}`;

        if (organisationCache[cacheKey]) {
          return organisationCache[cacheKey];
        }

        let organisationId = null;

        try {
          let existingOrganisation = null;

          if (partnerOrganisationRecordId) {
            const response = await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/Organisations/listRecords`,
              {
                maxRecords: 1,
                filterByFormula: `{Partner Record ID} = "${partnerOrganisationRecordId}"`
              },
              {
                headers: airtableHeadersWithJson
              }
            );
            existingOrganisation = response.data?.records?.[0] || null;
          }

          if (!existingOrganisation && normalisedPostcode) {
            const response = await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/Organisations/listRecords`,
              {
                maxRecords: 5,
                filterByFormula: `LOWER(TRIM({Name})) = "${normalisedName}"`
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            existingOrganisation =
              response.data?.records?.find((record) => {
                const fields = record.fields || {};
                const recordPostcode = (fields["Postcode"] || "").trim().toLowerCase();
                return recordPostcode === normalisedPostcode;
              }) || null;
          }

          if (!existingOrganisation) {
            const response = await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/Organisations/listRecords`,
              {
                maxRecords: 1,
                filterByFormula: `LOWER(TRIM({Name})) = "${normalisedName}"`
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            existingOrganisation = response.data?.records?.[0] || null;
          }

          const organisationFields = {
            Name: organisation.name,
            "Address Line 1": organisation.addressLine1 ?? null,
            "Address Line 2": organisation.addressLine2 ?? null,
            City: organisation.city ?? null,
            Postcode: organisation.postcode ?? null,
            County: organisation.county ?? null,
            "Partner Record ID": partnerOrganisationRecordId ?? null,
            "Partner Synced At": syncedAt
          };

          if (partnersRecordId) {
            organisationFields["Partner"] = [partnersRecordId];
          }

          if (existingOrganisation) {
            organisationId = existingOrganisation.id;
            await axios.patch(
              `${AIRTABLE_API}/${tisukBaseId}/Organisations/${organisationId}`,
              {
                fields: organisationFields
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            syncSummary.organisations.updated += 1;
          } else {
            const createdOrganisationResponse = await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/Organisations`,
              {
                fields: organisationFields
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            organisationId = createdOrganisationResponse.data?.id || null;

            syncSummary.organisations.created += 1;
          }
        } catch (error) {
          console.error("Error upserting Organisation in TISUK base.", error.message);
          throw error;
        }

        organisationCache[cacheKey] = organisationId;
        return organisationId;
      };

      // Helper to upsert a person in TISUK People table
      const upsertPerson = async (person, organisationId) => {
        if (!person) {
          return null;
        }

        const email = (person.email || "").trim();
        const normalisedEmail = email.toLowerCase();
        const displayName = (person.displayName || "").trim();
        const normalisedName = displayName.toLowerCase();
        const partnerPersonRecordId = person.partnerRecordId || null;
        const personKey = partnerPersonRecordId || normalisedEmail || `name:${normalisedName}`;

        if (peopleCache[personKey]) {
          return peopleCache[personKey];
        }

        let personId = null;

        try {
          let existingPerson = null;

          if (partnerPersonRecordId) {
            const existingByPartnerIdResponse = await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/People/listRecords`,
              {
                maxRecords: 1,
                filterByFormula: `{Partner Record ID} = "${partnerPersonRecordId}"`
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            existingPerson = existingByPartnerIdResponse.data?.records?.[0] || null;
          }

          if (!existingPerson && email) {
            const existingByEmailResponse = await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/People/listRecords`,
              {
                maxRecords: 1,
                filterByFormula: `LOWER(TRIM({Email})) = "${normalisedEmail}"`
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            existingPerson = existingByEmailResponse.data?.records?.[0] || null;
          }

          if (!existingPerson && displayName) {
            const existingByNameResponse = await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/People/listRecords`,
              {
                maxRecords: 1,
                filterByFormula: `LOWER(TRIM({Full Name})) = "${normalisedName}"`
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            existingPerson = existingByNameResponse.data?.records?.[0] || null;
          }

          const personFields = {
            Email: email || null,
            Role: person.role ?? null,
            Phone: person.phone ?? null,
            "Address Line 1": person.addressLine1 ?? null,
            "Address Line 2": person.addressLine2 ?? null,
            City: person.city ?? null,
            County: person.county ?? null,
            Postcode: person.postcode ?? null,
            "Partner Record ID": partnerPersonRecordId ?? null,
            "Partner Synced At": syncedAt
          };

          if (organisationId) {
            personFields["Organisation"] = [organisationId];
          }

          if (partnersRecordId) {
            personFields["Partner"] = [partnersRecordId];
          }

          if (existingPerson) {
            personId = existingPerson.id;
            await axios.patch(
              `${AIRTABLE_API}/${tisukBaseId}/People/${personId}`,
              {
                fields: personFields
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            syncSummary.people.updated += 1;
          } else {
            const createdPersonResponse = await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/People`,
              {
                fields: personFields
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            personId = createdPersonResponse.data?.id || null;

            syncSummary.people.created += 1;
          }
        } catch (error) {
          console.error("Error upserting Person in TISUK base.", error.message);
          throw error;
        }

        peopleCache[personKey] = personId;
        return personId;
      };

      // First, delete any Applications in TISUK that correspond to cancelled partner applications
      for (const partnerApplicationId of cancelledApplicationPartnerIds) {
        try {
          const existingApplicationResponse = await axios.post(
            `${AIRTABLE_API}/${tisukBaseId}/Applications/listRecords`,
            {
              maxRecords: 50,
              filterByFormula: `{Partner Record ID} = "${partnerApplicationId}"`
            },
            {
              headers: airtableHeadersWithJson
            }
          );

          const existingApplications = existingApplicationResponse.data?.records || [];

          for (const application of existingApplications) {
            await axios.delete(
              `${AIRTABLE_API}/${tisukBaseId}/Applications/${application.id}`,
              {
                headers: {
                  Accept: "application/json",
                  Authorization: `Bearer ${process.env.AIRTABLE_API_KEY}`
                }
              }
            );

            syncSummary.applications.deleted += 1;
          }
        } catch (error) {
          console.error("Error deleting cancelled Application(s) in TISUK base.", error.message);
          throw error;
        }
      }

      // Upsert Applications for active enrolments
      for (const enrolment of enrolments) {
        const partnerApplicationId = enrolment.id;
        const organisation = enrolment.organisation;
        const person = enrolment.people;

        try {
          const organisationId = await upsertOrganisation(organisation);
          const personId = await upsertPerson(person, organisationId);

          if (!personId) {
            // Cannot create an application without a linked person
            continue;
          }

          const applicationFields = {
            "Partner Record ID": partnerApplicationId,
            "Partner Synced At": syncedAt,
            Course: [tisukScheduledCourseId],
            Name: [personId],
            "Pack - Cards": enrolment.packCards ?? null,
            "Pack - Language": enrolment.packLanguage ?? null,
            "Pack - Appendix": enrolment.packAppendix ?? null,
            Status: "Confirmed"
          };

          const existingApplicationResponse = await axios.post(
            `${AIRTABLE_API}/${tisukBaseId}/Applications/listRecords`,
            {
              maxRecords: 1,
              filterByFormula: `{Partner Record ID} = "${partnerApplicationId}"`
            },
            {
              headers: airtableHeadersWithJson
            }
          );

          const existingApplication = existingApplicationResponse.data?.records?.[0] || null;

          if (existingApplication) {
            await axios.patch(
              `${AIRTABLE_API}/${tisukBaseId}/Applications/${existingApplication.id}`,
              {
                fields: applicationFields
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            syncSummary.applications.updated += 1;
          } else {
            await axios.post(
              `${AIRTABLE_API}/${tisukBaseId}/Applications`,
              {
                fields: applicationFields
              },
              {
                headers: airtableHeadersWithJson
              }
            );

            syncSummary.applications.created += 1;
          }
        } catch (error) {
          console.error("Error syncing Application in TISUK base.", error.message);
          if (error.response) {
            console.error("Airtable Applications error status:", error.response.status);
            console.error("Airtable Applications error data:", JSON.stringify(error.response.data, null, 2));
          }
          throw error;
        }
      }
    }

    res.status(200).send({
      summary: syncSummary
    });

  } catch (error) {
    console.error("Error fetching scheduled course for partner sync", error.message);
    res.status(500).send({
      error: "Error fetching scheduled course for partner sync",
      details: error.message
    });
  }

});

// #endregion


// --------------------------- BUILD SETTINGS

exports.api = onRequest(
  {
      memory: '1GiB',
      timeoutSeconds: 960,
      region: 'europe-west2',
  },
  app
)